import { defineTool as defineTool2 } from "npm:@lovable.dev/mcp-js@0.26.1";
import { z as z2 } from "npm:zod@^3.25.76";
var get_accommodation_default = defineTool2({
  name: "get_accommodation",
  title: "D\xE9tail d'un h\xE9bergement",
  description: "Obtenir la fiche d\xE9taill\xE9e d'un h\xE9bergement de Simandou S\xE9jour \xE0 partir de son identifiant.",
  inputSchema: { id: z2.string().describe(`Identifiant de l'h\xE9bergement, ex. "1".`) },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ id }) => {
    const item = accommodations.find((a) => a.id === id);
    if (!item) {
      return { content: [{ type: "text", text: `Aucun h\xE9bergement avec l'identifiant ${id}.` }], isError: true };
    }
    return {
      content: [{ type: "text", text: JSON.stringify(item, null, 2) }],
      structuredContent: { accommodation: item }
    };
  }
});

