var get_my_profile_default = defineTool3({
  name: "get_my_profile",
  title: "Mon profil",
  description: "R\xE9cup\xE9rer le profil Simandou S\xE9jour de l'utilisateur connect\xE9 (nom, langue, points, pr\xE9f\xE9rences).",
  inputSchema: {},
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async (_input, ctx) => {
    if (!ctx.isAuthenticated()) {
      return { content: [{ type: "text", text: "Non authentifi\xE9" }], isError: true };
    }
    const supabase = supabaseForUser(ctx);
    const { data, error } = await supabase.from("profiles").select("full_name, bio, phone, language, reward_points, badges, preferences, created_at").eq("user_id", ctx.getUserId()).maybeSingle();
    if (error) return { content: [{ type: "text", text: error.message }], isError: true };
    if (!data) return { content: [{ type: "text", text: "Aucun profil trouv\xE9 pour cet utilisateur." }] };
    return {
      content: [{ type: "text", text: JSON.stringify(data, null, 2) }],
      structuredContent: { profile: data }
    };
  }
});

