// src/lib/mcp/tools/create-review.ts
import { defineTool as defineTool6 } from "npm:@lovable.dev/mcp-js@0.26.1";
import { z as z5 } from "npm:zod@^3.25.76";
var create_review_default = defineTool6({
  name: "create_review",
  title: "Publier un avis",
  description: "Publier un avis (titre, commentaire, note sur 5) sur un h\xE9bergement au nom de l'utilisateur connect\xE9.",
  inputSchema: {
    accommodationId: z5.string().describe(`Identifiant de l'h\xE9bergement, ex. "1".`),
    title: z5.string().describe("Titre court de l'avis."),
    comment: z5.string().describe("Contenu de l'avis."),
    rating: z5.number().describe("Note de 1 \xE0 5.")
  },
  annotations: { readOnlyHint: false, destructiveHint: false, openWorldHint: false },
  handler: async ({ accommodationId, title, comment, rating }, ctx) => {
    if (!ctx.isAuthenticated()) {
      return { content: [{ type: "text", text: "Non authentifi\xE9" }], isError: true };
    }
    const note = Math.round(rating);
    if (note < 1 || note > 5) {
      return { content: [{ type: "text", text: "La note doit \xEAtre comprise entre 1 et 5." }], isError: true };
    }
    const supabase = supabaseForUser(ctx);
    const { data, error } = await supabase.from("reviews").insert({
      user_id: ctx.getUserId(),
      accommodation_id: accommodationId,
      title: title.trim(),
      comment: comment.trim(),
      rating: note
    }).select("id, accommodation_id, title, rating, created_at");
    if (error) return { content: [{ type: "text", text: error.message }], isError: true };
    return {
      content: [{ type: "text", text: JSON.stringify(data?.[0] ?? null, null, 2) }],
      structuredContent: { review: data?.[0] ?? null }
    };
  }
});

